import React, { useState, useEffect } from "react";
import axios from "axios";
import RoleSelection from "./RoleSelection";

function App() {
  const [isLogin, setIsLogin] = useState(true);
  const [form, setForm] = useState({});
  const [user, setUser] = useState(null);
  const [error, setError] = useState("");

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      axios.get("http://localhost:5000/api/profile", { headers: { Authorization: token } })
        .then(res => setUser(res.data))
        .catch(() => localStorage.removeItem("token"));
    }
  }, []);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
    setError("");
  };

  const submitForm = async () => {
    if (!form.username || !form.password || (!isLogin && !form.email)) {
      setError("❌ All fields are required!");
      return;
    }
    if (!isLogin && form.password !== form.confirmPassword) {
      setError("❌ Passwords do not match!");
      return;
    }

    try {
      if (isLogin) {
        const res = await axios.post("http://localhost:5000/api/login", form);
        localStorage.setItem("token", res.data.token);
        setUser(res.data.user);
      } else {
        await axios.post("http://localhost:5000/api/register", form);
        alert("✅ Registration successful! Please login.");
        setIsLogin(true);
      }
    } catch (err) {
      setError(`❌ ${err.response?.data?.msg || "Server error"}`);
    }
  };

  const logout = () => {
    localStorage.removeItem("token");
    setUser(null);
  };

  if (user) return <RoleSelection user={user} logout={logout} />;

  return (
    <div className="flex h-screen items-center justify-center bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500">
      <div className="bg-white shadow-xl p-8 rounded-2xl w-96">
        <h2 className="text-2xl font-bold text-center mb-4 text-purple-600">
          {isLogin ? "Login" : "Register"}
        </h2>

        {error && <div className="bg-red-100 text-red-700 p-2 rounded mb-2 text-center">{error}</div>}

        {!isLogin && (
          <input name="email" onChange={handleChange} placeholder="Email"
            className="w-full p-2 mb-2 border rounded-lg focus:ring-2 focus:ring-purple-400" />
        )}

        <input name="username" onChange={handleChange} placeholder="Username"
          className="w-full p-2 mb-2 border rounded-lg focus:ring-2 focus:ring-purple-400" />

        <input type="password" name="password" onChange={handleChange} placeholder="Password"
          className="w-full p-2 mb-2 border rounded-lg focus:ring-2 focus:ring-purple-400" />

        {!isLogin && <>
          <input type="password" name="confirmPassword" onChange={handleChange} placeholder="Confirm Password"
            className="w-full p-2 mb-2 border rounded-lg focus:ring-2 focus:ring-purple-400" />
          <input name="pin" onChange={handleChange} placeholder="Login PIN (optional)"
            className="w-full p-2 mb-2 border rounded-lg focus:ring-2 focus:ring-purple-400" />
          <select name="loginType" onChange={handleChange}
            className="w-full p-2 mb-2 border rounded-lg focus:ring-2 focus:ring-purple-400">
            <option value="password">Password</option>
            <option value="pin">PIN</option>
            <option value="voice">Voice</option>
          </select>
        </>}

        <button onClick={submitForm}
          className="w-full bg-purple-600 text-white p-2 rounded-lg hover:bg-purple-800 transition-colors duration-300">
          {isLogin ? "Login" : "Register"}
        </button>

        <p className="mt-3 text-center text-sm">
          {isLogin ? "Don't have an account?" : "Already have an account?"}{" "}
          <span onClick={() => { setIsLogin(!isLogin); setError(""); }}
            className="text-indigo-600 cursor-pointer font-semibold hover:underline">
            {isLogin ? "Register" : "Login"}
          </span>
        </p>
      </div>
    </div>
  );
}

export default App;
